import sys

def main():
    s = sys.stdin.read().split()[0]
    cnt = {}
    order = []
    for ch in s:
        if ch not in cnt:
            cnt[ch] = 0
            order.append(ch)
        cnt[ch] += 1
    out = []
    active = order
    while active:
        nxt = []
        for ch in active:
            out.append(ch)
            cnt[ch] -= 1
            if cnt[ch]:
                nxt.append(ch)
        active = nxt
    print(''.join(out))

main()

